<?php
function apply_research_update(): void {
 if(record('settings','research-2026-10',true))return;
 $save=function($type,$slug,$title,$data,$status='published'){
  $existing=record($type,$slug,true);
  if($existing)query('UPDATE content SET title=?,status=?,data=?,updated_at=? WHERE id=?',[$title,$status,json_encode(array_replace($existing['fields'],$data),JSON_UNESCAPED_UNICODE),now(),$existing['id']]);
  else query('INSERT INTO content(type,slug,title,status,data,updated_at) VALUES(?,?,?,?,?,?)',[$type,$slug,$title,$status,json_encode($data,JSON_UNESCAPED_UNICODE),now()]);
 };
 $home=settings('home');$defaults=home_defaults();foreach(['heading','accent','intro','hero_image','image_caption','about_image','usp_eyebrow','usp_heading','usp_body','usp_image','usp_source','usp_video','gallery_intro'] as $key)$home[$key]=$defaults[$key];
 $home['about_heading']='An Ambala story. An Olympic milestone.';$home['about_body']="Abhishek Rana’s coaching story is closely linked to Sarabjot Singh’s rise in Indian shooting. Their partnership began in Ambala in 2016 and continued through Sarabjot’s Paris 2024 Olympic bronze in the 10m air pistol mixed team event.\n\nToday, explore air rifle and air pistol training, start with a demo, or speak to the academy about your next competition goal. Our approach brings attention to technique, focus and preparation.";
 $save('settings','home','Homepage',$home);
 $save('settings','site','Website settings',['logo'=>'/assets/images/academy-logo.webp','phone'=>'+91 99967 60097','instagram'=>'https://www.instagram.com/abhishekranashootingacademy/','tagline'=>'Your ambition. Olympic experience.','illustration_notice'=>'Academy media is sourced from AR Shooting Academy’s existing website. Other Indian sport and range reference photos are individually credited; their use does not imply affiliation.']);
 $save('coaches','abhishek-rana','Abhishek Rana',['role'=>'Founder & shooting coach','credentials'=>'Personal coach of Paris 2024 Olympic bronze medallist Sarabjot Singh','branch'=>'Ambala, Haryana','body'=>"Abhishek Rana is the personal coach of Indian air pistol shooter Sarabjot Singh. They began working together in Ambala in 2016.\n\nSarabjot won bronze alongside Manu Bhaker in the 10m air pistol mixed team event at Paris 2024. Government of India coverage recognises Abhishek Rana’s role in Sarabjot’s preparation for the Games.\n\nExplore training at the academy, or enquire about guidance for technique, focus and competition preparation. Session availability is confirmed by the academy.",'image'=>'/assets/images/coach-abhishek.webp']);
 $save('achievements','sarabjot-paris-2024','Sarabjot Singh · Olympic bronze',['athlete'=>'Sarabjot Singh','event'=>'Paris 2024 · 10m Air Pistol Mixed Team','date'=>'2024-07-30','result'=>'Olympic bronze · India','body'=>'Sarabjot Singh, coached by Abhishek Rana, won bronze alongside Manu Bhaker in the 10m air pistol mixed team event at Paris 2024. This result celebrates Sarabjot’s performance and the longstanding coaching partnership behind his journey.','image'=>'/assets/images/sarabjot-medal.webp','source_url'=>'https://www.issf-sports.org/athletes/SHINDM3009200101']);
 $save('pages','about','About the academy',['heading'=>'From Ambala. With bigger ambitions.','intro'=>'Discover the academy led by Abhishek Rana, personal coach of Olympic bronze medallist Sarabjot Singh.','body'=>$home['about_body']]);
 $save('pages','coaches','Coaches & team',['intro'=>'Meet Abhishek Rana, personal coach of Olympic bronze medallist Sarabjot Singh.','body'=>'Learn more about the coaching experience behind the academy.']);
 $save('pages','achievements','Achievements',['heading'=>'The journey behind the medal','intro'=>'Celebrating verified competition results and the athletes behind them.','body'=>'Sarabjot Singh’s Olympic result is part of a coaching journey with Abhishek Rana that began in Ambala in 2016.']);
 $save('pages','photo-credits','Photo credits',['intro'=>'Academy media and licensed photographs of Indian shooting sport.','body'=>'Academy photographs and branding were imported from the existing AR Shooting Academy website linked by its official Instagram profile. Additional Indian sport and range reference photographs are individually attributed below. No affiliation is implied for unrelated reference athletes or facilities. Images are resized, converted to WebP and may be cropped for display.']);
 foreach([['academy-coach','Meet coach Abhishek Rana','/assets/images/coach-abhishek.webp','Abhishek Rana at his desk. Source: existing AR Shooting Academy website.'],['academy-paris-story','The coach and the medallist','/assets/images/academy-training.webp','Academy poster featuring Abhishek Rana and Sarabjot Singh.'],['academy-sarabjot','A moment of pride','/assets/images/academy-moment.webp','Academy poster celebrating Sarabjot Singh.']] as [$slug,$title,$image,$caption])$save('gallery',$slug,$title,['category'=>'From the academy','caption'=>$caption,'image'=>$image]);
 foreach(['academy-coach','academy-paris-story','academy-sarabjot'] as $i=>$slug)query('UPDATE content SET sort_order=? WHERE type=? AND slug=?',[-10+$i,'gallery',$slug]);
 $save('settings','research-2026-10','Research content applied',['version'=>'1']);
}
